public class Main {
    public static void main(String[] args) {
        Person p1 = new Person("A");
        Person p2 = new Person("B");

        p1.friend = p2; // p1 references p2

        p2 = null; 
        // Is Person("B") garbage? NO.
        // p1 (Stack/GC Root) -> Person("A") -> Person("B")
        // "B" is still REACHABLE through "A".

        p1 = null;
        // Now Stack -> x
        // Both Person("A") and Person("B") are unreachable.
        // GC will collect both.
    }
}

class Person {
    String name;
    Person friend;
    public Person(String name) { this.name = name; }
}
